// Scroll stories, shared by stop.html (shell.js: one car) and teaser.html (teaser.js: the teaser cars). Scrolled to, a car's
// stage (museum photo / 3-D model) pins, above the steps on a phone held upright and beside them otherwise, and only the
// steps move on: the introduction over the museum photo (with car.look, the one thing to find on the exhibit), one step
// per component in 3D, then background back on the photo with the car outline (car.takeaway first). A component step reads
// as one experiment: its prompt, the mechanism's key cards, its answer, then the rest under a disclosure named by
// component.more (panel.js `detail`); without `more` its cards and technical facts follow in order. The step at the reading
// line sets what the stage shows; only stages on screen run their frame loop.
import { t } from "./i18n.js";
import { h } from "./dom.js";
import { stageElement, mountViewer, caveats } from "./viewer.js";

// A step is its content and what the stage shows while it is at the reading line.
const step = (state, ...kids) => ({ state, el: h("section", { class: "step" }, kids) });
// What to look at on the real car, before the model and after it.
const look = (label, text) => (text ? h("p", { class: "look" }, h("b", {}, label), " ", text) : null);

// A component's step, with the elements its panel cards go into.
function compStep(c) {
  const main = h("div", { class: "cards" }), detail = c.more ? h("div", { class: "cards" }) : main;
  const st = step({ comp: c.id, view: "model", outline: false }, h("h3", {}, c.label),
    c.prompt ? h("p", { class: "prompt" }, c.prompt) : null, main, c.answer ? h("p", { class: "answer" }, c.answer) : null,
    c.more ? h("details", { class: "more" }, h("summary", {}, c.more), detail) : null);
  return { ...st, slots: { main, detail } };
}

// One car's story, not yet playing. title: the tag of the car's title ("h1" on its own page); more: what closes the
// background step (the teaser's link to the stop page).
export function story(car, { title = "h2", more = null } = {}) {
  const first = car.components[0].id;
  const comps = car.components.map(compStep);
  const steps = [
    step({ comp: first, view: "photo", outline: false }, h("div", { class: "eyebrow" }, car.eyebrow), h(title, {}, car.title), h("p", { class: "lede" }, car.lede),
      look(t("At the car:"), car.look)),
    ...comps,
    step({ comp: first, view: "photo", outline: true }, look(t("Back at the car:"), car.takeaway), h("footer", {}, h("h3", {}, t("Background")),
      h("p", {}, t("Back on the museum photo: the mechanism where it sits, inside the car's outline.")),
      car.note ? h("p", {}, car.note) : null, ...caveats(car), more)),
  ];
  steps[0].el.classList.add("on");
  const stageEl = stageElement(car);
  const el = h("article", { class: "story", "aria-label": car.name }, h("div", { class: "story-stage" }, stageEl), h("div", { class: "steps" }, steps.map(s => s.el)));
  return { car, el, stageEl, steps, comps, at: 0, viewer: null };
}

// Loads the stories' 3-D views (already in the page) and lets the scroll drive them. Returns one ?debug handle per story.
export async function play(stories) {
  await Promise.all(stories.map(async s => {
    try {
      s.viewer = await mountViewer(s.car, s.stageEl, comp => s.comps[s.car.components.indexOf(comp)].slots);
      s.viewer.show(s.steps[0].state);
    } catch (err) {
      console.error(err);
      s.stageEl.after(h("p", { class: "fail" }, t("The 3D view could not load. Check your connection and reload the page; after one visit with signal it also works offline.")));
    }
  }));

  // The reading line: halfway down the screen beside the pinned stage, or halfway down the part it leaves free below it.
  // The last step whose top has passed the line is the one shown.
  function pick() {
    for (const s of stories) {
      const pane = s.stageEl.parentElement.getBoundingClientRect(), beside = s.steps[0].el.getBoundingClientRect().left >= pane.right;
      const line = beside ? innerHeight / 2 : (pane.bottom + innerHeight) / 2;
      let at = 0;
      s.steps.forEach((st, i) => { if (st.el.getBoundingClientRect().top < line) at = i; });
      if (at === s.at) continue;
      const before = s.steps[s.at].state;
      s.at = at;
      s.steps.forEach((st, i) => st.el.classList.toggle("on", i === at));
      if (s.viewer && s.steps[at].state !== before) s.viewer.show(s.steps[at].state);
    }
  }
  let queued = false;
  const schedule = () => { if (!queued) { queued = true; requestAnimationFrame(() => { queued = false; pick(); }); } };
  addEventListener("scroll", schedule, { passive: true });
  addEventListener("resize", schedule);
  pick();

  // Only stages on screen animate: several scenes at once, one of them a live wind tunnel, would be too much for a phone.
  const onScreen = new IntersectionObserver(entries => {
    for (const e of entries) { const v = stories.find(s => s.stageEl === e.target).viewer; if (e.isIntersecting) v.start(); else v.stop(); }
  });
  for (const s of stories) if (s.viewer) onScreen.observe(s.stageEl);

  return stories.map(s => ({
    slug: s.car.slug, step: () => s.at, state: () => s.viewer?.state,
    frames: () => s.viewer?.stage.stats.frames ?? 0, triangles: () => s.viewer?.stage.renderer.info.render.triangles ?? 0,
  }));
}
// Declarative side-panel cards. A subsystem describes its cards; this builds the DOM (textContent only) and returns handles.
// Card: { label, badge?: { id, text }, only?: "model" | "photo", detail?, items: [widget] }. Widgets (one key each, plus
// optional `only` and `detail`):
//   readouts: [{ id, label, unit, value }]          → ui.set(id, text)
//   trace: { id, series: [{ token, min, max }], span, top, bottom, aria }   → ui.trace(id).push(t, [v…]) / .draw(t)
//   buttons: [{ id, label, toggle?: [onLabel, offLabel], pressed?, onClick(pressed) }]   → ui.toggle(id).set(bool)
//   slider: { id, label, min, max, step, value, onInput(v) }   → ui.slider(id).set(v)
//   meter: { id }  → ui.meter(id).set(0..1, hot)        cells: { id, labels }  → ui.cells(id).set(i, text, on)
//   legend: [[token, name]]   key: [[token, text]]   svg: { id, viewBox, aria }  → ui.el(id)   text: "…"   list: ["…"]
// Text arrives already translated (subsystems use ctx.t); readout values are written with the local decimal mark.
// Element ids are `${scope}-${id}`: scope defaults to the component id; pages with several cars pass one per car.
// Depth: a widget or card marked `detail` (readings, legends, secondary controls) goes to detailContainer, the story's named
// disclosure under the mechanism's key experiment; the rest of its card stays in container. Without a separate
// detailContainer every card stays whole, in order. A split card keeps its label (and badge) on the part in container;
// its part in detailContainer repeats the label's text.
import { num } from "./i18n.js";
import { h } from "./dom.js";

export function createPanel(container, compId, scope = compId, detailContainer = container) {
  const els = new Map(), api = {};
  const key = id => `${scope}-${id}`;

  const widgets = {
    readouts: items => h("div", { class: "readouts" }, items.map(r => {
      const o = h("output", { id: key(r.id) }, r.value == null ? "–" : num(r.value)); els.set(r.id, o);
      return h("div", {}, h("small", {}, r.label), o, h("small", {}, r.unit ?? ""));
    })),
    trace: t => {
      const svg = h("svg:svg", { viewBox: "0 0 280 110", role: "img", "aria-label": t.aria ?? "" });
      const grid = [[55, null], [5, "2 3"], [105, "2 3"]].map(([y, dash]) => h("svg:line", { x1: 0, y1: y, x2: 280, y2: y, stroke: "var(--rule)", "stroke-dasharray": dash }));
      const lines = t.series.map(s => h("svg:polyline", { fill: "none", stroke: `var(${s.token})`, "stroke-width": 1.6 }));
      svg.append(...grid, ...lines, h("svg:text", { x: 278, y: 15, "text-anchor": "end" }, t.top ?? ""), h("svg:text", { x: 278, y: 101, "text-anchor": "end" }, t.bottom ?? ""));
      const buf = [], span = t.span ?? 6;
      els.set(t.id, {
        push(time, values) { buf.push({ time, values }); },
        draw(now) {
          while (buf.length && buf[0].time < now - span) buf.shift();
          const X = tt => ((tt - (now - span)) / span * 280).toFixed(1);
          t.series.forEach((s, i) => lines[i].setAttribute("points", buf.map(p => {
            const v = Math.max(s.min, Math.min(s.max, p.values[i]));
            return `${X(p.time)},${(105 - (v - s.min) / (s.max - s.min) * 100).toFixed(1)}`;
          }).join(" ")));
        },
      });
      return h("div", { class: "trace" }, svg);
    },
    buttons: items => h("div", { class: "row" }, items.map(b => {
      // toggle: [onLabel, offLabel] flips itself; pressed without toggle = radio-style button whose state the caller sets.
      const el = h("button", { type: "button", "aria-pressed": b.toggle || b.pressed != null ? String(!!b.pressed) : null }, b.toggle ? b.toggle[b.pressed ? 0 : 1] : b.label);
      const handle = { el, pressed: !!b.pressed, set(p) { handle.pressed = p; el.setAttribute("aria-pressed", String(p)); if (b.toggle) el.textContent = b.toggle[p ? 0 : 1]; } };
      el.addEventListener("click", () => { if (b.toggle) handle.set(!handle.pressed); b.onClick?.(handle.pressed); });
      els.set(b.id, handle);
      return el;
    })),
    slider: s => {
      const input = h("input", { id: key(s.id), type: "range", min: s.min, max: s.max, step: s.step ?? 1, value: s.value });
      input.addEventListener("input", () => s.onInput?.(+input.value));
      els.set(s.id, { el: input, set(v) { input.value = v; } });
      return h("div", { class: "slider" }, h("label", { class: "label", for: key(s.id) }, s.label), input);
    },
    meter: m => { const bar = h("i"), el = h("div", { class: "meter" }, bar); els.set(m.id, { set(f, hot) { bar.style.width = `${(Math.max(0, Math.min(1, f)) * 100).toFixed(0)}%`; el.classList.toggle("hot", !!hot); } }); return el; },
    cells: c => {
      const cells = c.labels.map(l => h("div", { class: "cyl" }, h("b", {}, l), h("span", {}, "–")));
      els.set(c.id, { set(i, text, on) { const el = cells[i]; if (el.dataset.s !== text) { el.dataset.s = text; el.lastChild.textContent = text; } el.classList.toggle("power", !!on); } });
      return h("div", { class: "cyls", style: `--n:${Math.min(c.labels.length, 4)}` }, cells);
    },
    legend: items => h("ul", { class: "legend" }, items.map(([tok, name]) => h("li", {}, h("span", { class: "sw", style: `background:var(${tok})` }), name))),
    key: items => h("div", { class: "key" }, items.map(([tok, text]) => h("span", {}, h("i", { style: `background:var(${tok})` }), text))),
    svg: s => { const el = h("svg:svg", { viewBox: s.viewBox, role: "img", "aria-label": s.aria ?? "", class: "diagram" }); els.set(s.id, el); return el; },
    text: t => h("p", { class: "note" }, t),
    list: items => h("ul", { class: "talk" }, items.map(t => h("li", {}, t))),
  };

  // Append cards; returns the shared handle API (call again to add more cards for the same component).
  return function cards(list) {
    const split = detailContainer !== container;
    for (const card of list) {
      const label = h("div", { class: "label" }, card.label ?? "");
      if (card.badge) { const b = h("span", { class: "badge" }, card.badge.text); label.append(" · ", b); els.set(card.badge.id, { set(text, on) { b.textContent = text; b.classList.toggle("on", !!on); } }); }
      const items = card.items ?? [], deep = w => split && (card.detail || w.detail);
      const main = items.filter(w => !deep(w)), more = items.filter(deep);
      const box = (lab, ws, into) => {
        if (!ws.length && !lab) return;
        const el = h("div", { class: "panel", "data-comp": compId, "data-only": card.only }, lab);
        for (const w of ws) {
          const [type] = Object.keys(w).filter(k => k !== "only" && k !== "detail");
          const node = widgets[type](w[type]);
          if (w.only) node.dataset.only = w.only;
          el.append(node);
        }
        into.append(el);
      };
      const head = main.length > 0 || !more.length;   // the label goes where the card's experiment is
      box(head ? label : null, main, container);
      box(head ? (more.length && card.label ? h("div", { class: "label" }, card.label) : null) : label, more, detailContainer);
    }
    return Object.assign(api, {
      set: (id, text) => { els.get(id).value = num(text); },
      el: id => els.get(id), trace: id => els.get(id), toggle: id => els.get(id), slider: id => els.get(id),
      meter: id => els.get(id), cells: id => els.get(id), badge: id => els.get(id),
    });
  };
}
