    credit: { author: "Valder137", license: "CC BY 2.0", url: "https://commons.wikimedia.org/wiki/File:Mercedes-Benz_300SL_1955_Fl%C3%BCgelt%C3%BCren_Gullwing_Coup%C3%A8_RSideFront_MBMuse_9June2013_(14797075767).jpg" },
  },
  components: [
